<template><div class="select-list"><button v-for="option in options" :key="option.value||option" class="select-item" :class="{selected:(option.value||option)===modelValue}" type="button" @click="select(option)"><span>{{option.text||option}}</span><span v-if="(option.value||option)===modelValue" class="check">✓</span></button></div></template>
<script setup>defineProps({options:{type:Array,default:()=>[]},modelValue:{type:[String,Number],default:''}});const emit=defineEmits(['update:modelValue','select']);function select(option){const value=option.value||option;emit('update:modelValue',value);emit('select',option)}</script>
<style scoped>.select-list{width:100%;display:flex;flex-direction:column;gap:12px;padding:0;background:#fff;border-radius:12px;overflow:hidden}.select-item{width:100%;min-height:44px;padding:10px 16px;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;border:0;color:#1D2129;background:#fff;font:500 16px/24px "PingFang SC",sans-serif;text-align:left}.select-item+.select-item{border-top:1px solid #F2F3F5}.select-item .check{color:#00AAA6;font-size:20px;font-weight:600}</style>
